import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Commercial Advertising Image Presets & Qwen Image 2.1 ComfyUI Virtual Ambassador Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/06-ai-media-and-video-studio/commercial-image-and-qwen-ambassador/spec.md","filePath":"feature/modules/06-ai-media-and-video-studio/commercial-image-and-qwen-ambassador/spec.md"}'),i={name:"feature/modules/06-ai-media-and-video-studio/commercial-image-and-qwen-ambassador/spec.md"};function s(d,e,c,n,l,m){return t(),o("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="commercial-advertising-image-presets-qwen-image-2-1-comfyui-virtual-ambassador-pipeline" tabindex="-1">Commercial Advertising Image Presets &amp; Qwen Image 2.1 ComfyUI Virtual Ambassador Pipeline <a class="header-anchor" href="#commercial-advertising-image-presets-qwen-image-2-1-comfyui-virtual-ambassador-pipeline" aria-label="Permalink to &quot;Commercial Advertising Image Presets &amp; Qwen Image 2.1 ComfyUI Virtual Ambassador Pipeline&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>commercial-image-and-qwen-ambassador</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>06-ai-media-and-video-studio</code> — AI Commercial Image, Product Video &amp; Conversational Video Studio</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>commercial-image-presets</code>, <code>ambassador-portrait-ui</code>, <code>qwen-ambassador-docker</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/06-ai-features/3-7-7-generate-ambassador/spec.html">FR 3.7.7 — Generate Ambassador</a> · <a href="./../../../srs/06-ai-features/3-7-8-view-image-style-template/spec.html">FR 3.7.8 — View Image Style Template</a> · <a href="./../../../srs/06-ai-features/3-7-9-generate-image/spec.html">FR 3.7.9 — Generate Image</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Deliver BrandHub&#39;s self-hosted / GPU-worker <strong>Virtual Brand Ambassador &amp; Commercial Product Advertising Image Pipeline</strong>: containerized <strong>Qwen Image 2.1 ComfyUI Worker</strong> (<code>qwen-ambassador-docker</code>), <strong>Ambassador Portrait &amp; Multi-Angle Character Sheet UI</strong> (<code>ambassador-portrait-ui</code>), and <strong>3-Image Commercial Advertising Composition Presets</strong> (<code>commercial-image-presets</code> via <code>/api/v2/commercial/generate</code> combining Ambassador identity + Product photo + Pose/Style preset across <code>4:5</code>, <code>9:16</code>, <code>16:9</code>, and <code>auto</code> aspect buckets).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code>, <code>Manager</code>, or <code>Creator</code>, I want to generate consistent Virtual Brand Ambassadors (<code>POST /api/v1/ai/ambassadors/generate</code> &amp; <code>/character-sheet</code>) and composite them holding or showcasing real client products (<code>POST /api/v1/ai/image/commercial/generate</code>) using curated commercial studio lighting presets without prompt-engineering complexity.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Containerized Qwen Image 2.1 ComfyUI Runtime (<code>qwen-ambassador-docker</code>):</strong> <code>QwenAmbassadorClient</code> (<code>app/services/qwen_ambassador_client.py</code>) dispatches deterministic ComfyUI workflow graphs to the Dockerized GPU worker with health checks, bounded concurrency, and automatic PNG normalization (<code>&lt;= 20 MB</code> input guard, RGB lossless conversion in <code>commercial_image.py</code>).</li><li><strong>Ambassador Portrait &amp; Character Sheet UI (<code>ambassador-portrait-ui</code>):</strong> <code>pages/ai-studio/ambassadors.tsx</code> (<code>CreateAmbassadorDialog.tsx</code>, <code>AmbassadorGrid.tsx</code>, <code>AmbassadorCard.tsx</code>, <code>AmbassadorGeneratorModal.tsx</code>) supports demographic/wardrobe/brand-persona controls, 1:1 / 3:4 portrait framing, and multi-angle character sheets (<code>FREE_V1</code> / configured credit rules).</li><li><strong>Commercial Advertising Style Presets (<code>commercial-image-presets</code>):</strong> <code>app/services/image/model_presets.py</code> and <code>app/api/v2/endpoints/commercial_image.py</code> (<code>POST /api/v2/commercial/generate</code>) fuse Ambassador reference (<code>PRESET</code> or custom Workspace ambassador) + Product image + Scene/Pose preset across aspect buckets <code>4:5</code> (<code>896x1120</code>), <code>9:16</code> (<code>576x1024</code>), <code>16:9</code> (<code>1024x576</code>), <code>1:1</code> (<code>1024x1024</code>), or <code>auto</code>, enforced by <code>safety_guardrails.py</code> (<code>validate_prompt_safety</code>) and <code>DA-974</code> <code>AMBASSADOR_GENERATE</code> / <code>COMMERCIAL_IMAGE</code> credit settlement.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>aiStudio.ambassador.*</code>, <code>aiStudio.commercialImage.*</code>, <code>aiStudio.imageStyles.*</code> in <code>src/i18n/locales/{vi,en}/aiStudio.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/ai-studio/ambassadors.tsx</code>, <code>CreateAmbassadorDialog.tsx</code>, <code>AmbassadorGeneratorModal.tsx</code>, <code>pages/editor/components/{AIImageStudioPanel,AIImageToolsPanel,ImageLightboxModal}.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/{AiModelGeneratorScreen,AiAdImageScreen}.tsx</code>, <code>src/utils/saveToLibrary.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/ai/ambassadors/presets</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>AiGenerationController</code> -&gt; <code>ambassador.py</code> &amp; <code>model_presets.py</code> (0-credit catalog)</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/ai/ambassadors/generate &amp; /character-sheet</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>) + <code>Idempotency-Key</code></td><td style="text-align:left;"><code>AiGenerationController</code> -&gt; <code>ambassador.py</code> -&gt; <code>QwenAmbassadorClient</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/ai/image/commercial/generate</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>) + <code>Idempotency-Key</code></td><td style="text-align:left;"><code>AiGenerationController</code> -&gt; <code>app/api/v2/endpoints/commercial_image.py</code> (<code>POST /commercial/generate</code>)</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Corrupt / <code>&gt; 20 MB</code> Base64 Product Image:</strong> Rejected <code>413</code> or <code>422</code> in <code>_normalize_image_bytes()</code> before reserving GPU worker time, releasing held AI credits immediately.</li><li><strong>NSFW / Unsafe Prompt Guardrail:</strong> <code>validate_prompt_safety()</code> blocks prohibited prompts (<code>422</code>) prior to ComfyUI execution.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/06-ai-features/3-7-7-generate-ambassador/spec.html">FR 3.7.7 — Generate Ambassador</a> · <a href="./../../../srs/06-ai-features/3-7-8-view-image-style-template/spec.html">FR 3.7.8 — View Image Style Template</a> · <a href="./../../../srs/06-ai-features/3-7-9-generate-image/spec.html">FR 3.7.9 — Generate Image</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/06-ai-features.html">BA 06 AI Features</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const u=a(i,[["render",s]]);export{p as __pageData,u as default};
